when.condition:
@{
          if (string.Equals("{{entra-workload-app-role}}", "disabled", StringComparison.Ordinal)) { return false; }
          var presented = context.Request.Headers.GetValueOrDefault("Authorization", "").Split(' ').LastOrDefault() ?? string.Empty;
          var unverified = presented.AsJwt();
          return unverified != null && unverified.Claims.ContainsKey("roles") && !unverified.Claims.ContainsKey("scp");
        }

set-variable.value:
@{
        var jwt = (Jwt)context.Variables["jwt"];
        if (jwt.Claims.ContainsKey("azp")) { return jwt.Claims["azp"][0]; }
        if (jwt.Claims.ContainsKey("appid")) { return jwt.Claims["appid"][0]; }
        return string.Empty;
      }

send-request.set-body:
@{
              var jwt = (Jwt)context.Variables["jwt"];
              var body = new JObject(
                new JProperty("tenantId", jwt.Claims.ContainsKey("tid") ? jwt.Claims["tid"][0] : "{{entra-tenant-id}}"),
                new JProperty("subjectId", jwt.Subject),
                new JProperty("applicationId", (string)context.Variables["callerApplicationId"]),
                // Which of the two token shapes was validated. The control plane cannot tell a
                // person from an unattended workload by the claims alone, and the two are
                // governed differently, so the gateway states which validator accepted it.
                new JProperty("authenticationFlow", (string)context.Variables["authenticationFlow"]),
                new JProperty("apiFamily", (string)context.Variables["apiFamily"])
              );
              // Stated on every request, because an omitted claim and a caller in no
              // assigned group look identical from here. Sending nothing would leave the
              // control plane unable to tell a removal from an unconfigured gateway.
              body.Add(new JProperty("groups", jwt.Claims.ContainsKey("groups") ? new JArray(jwt.Claims["groups"]) : new JArray()));
              return body.ToString(Newtonsoft.Json.Formatting.None);
            }

set-variable.value:
@{
                try
                {
                    var envelope = ((IResponse)context.Variables["policyResponse"]).Body.As<JObject>(preserveContent: true);
                    var document = envelope?["document"] as JObject;
                    var attribution = document?["attribution"] as JObject;
                    var allowedModels = document?["allowedModels"] as JArray;
                    var modelDeployments = document?["modelDeployments"] as JArray;
                    var limits = document?["limits"] as JArray;
                    if (document == null ||
                        !string.Equals((string)document["contractVersion"], "v1", StringComparison.Ordinal) ||
                        !string.Equals((string)document["documentType"], "effective-policy", StringComparison.Ordinal) ||
                        !string.Equals((string)document["resolution"], "resolved", StringComparison.Ordinal) ||
                        document["configVersion"] == null || document["configVersion"].Type != JTokenType.Integer || (int)document["configVersion"] < 1 ||
                        attribution == null ||
                        string.IsNullOrWhiteSpace((string)attribution["subjectKey"]) ||
                        string.IsNullOrWhiteSpace((string)attribution["applicationKey"]) ||
                        allowedModels == null || !allowedModels.HasValues ||
                        modelDeployments == null || !modelDeployments.HasValues ||
                        limits == null || !limits.HasValues)
                    {
                        return "";
                    }
                    return document.ToString(Newtonsoft.Json.Formatting.None);
                }
                catch
                {
                    return "";
                }
              }

@{
                try
                {
                    var envelope = ((IResponse)context.Variables["policyResponse"]).Body.As<JObject>(preserveContent: true);
                    if (envelope == null) { return ""; }
                    if (envelope.Property("document") == null || envelope["document"].Type != JTokenType.Null) { return ""; }
                    var reason = envelope["reasonCode"];
                    if (reason == null || reason.Type != JTokenType.String) { return ""; }
                    var code = (string)reason;
                    return (code == "membership-evidence-unmapped" || code == "model-intersection-empty" || code == "principal-not-entitled") ? code : "";
                }
                catch
                {
                    return "";
                }
              }

@{
        var team = ((JObject)context.Variables["effectivePolicy"])["attribution"]["teamKey"];
        return team == null || team.Type == JTokenType.Null ? "" : (string)team;
      }

return-response.set-body:
@{
              var allowed = new JArray(((JArray)((JObject)context.Variables["effectivePolicy"])["allowedModels"]).Values<string>());
              return new JObject(new JProperty("error", new JObject(
                new JProperty("message", "The requested model is not allowed."),
                new JProperty("type", "permission_error"),
                new JProperty("param", "model"),
                new JProperty("code", "model_not_allowed"),
                new JProperty("allowed_models", allowed)))).ToString(Newtonsoft.Json.Formatting.None);
            }

