@{
        var policy = (JObject)context.Variables["effectivePolicy"];
        var requested = (string)context.Variables["requestedModel"];
        var fallback = (JObject)policy["fallback"];
        if (fallback == null || !(bool)fallback["enabled"]) { return requested; }

        var intent = policy["modelSelectionIntent"] == null ? "pinned" : (string)policy["modelSelectionIntent"];
        if (intent != "preferred") { return requested; }

        var threshold = policy["warnThresholdPercent"] == null ? 0 : (int)policy["warnThresholdPercent"];
        if (threshold <= 0) { return requested; }

        var limits = (JArray)policy["limits"];
        var scopes = new [] { "organization", "team", "subject", "application" };
        var names = new [] { "remainingOrganizationTokens", "remainingTeamTokens", "remainingSubjectTokens", "remainingApplicationTokens" };
        var breached = false;
        for (var i = 0; i < scopes.Length; i++)
        {
          if (!context.Variables.ContainsKey(names[i])) { continue; }
          var scope = scopes[i];
          var limit = limits.FirstOrDefault(l => (string)l["scope"] == scope && (string)l["modelScope"] == "all-models");
          if (limit == null) { continue; }
          var quota = Convert.ToInt64(limit["tokenQuota"]);
          if (quota <= 0) { continue; }
          var remaining = Convert.ToInt64(context.Variables[names[i]]);
          if (((decimal)(quota - remaining) / (decimal)quota) * 100m >= threshold) { breached = true; }
        }
        // A model-scoped budget cannot be read from a counter here: the per-model counter
        // runs after this decision. The resolver carries the share it has already burned.
        var pressure = (JArray)policy["modelPressure"];
        if (pressure != null)
        {
          var entry = pressure.FirstOrDefault(p => (string)p["model"] == requested);
          if (entry != null && (int)entry["consumedBasisPoints"] >= threshold * 100) { breached = true; }
        }
        if (!breached) { return requested; }

        var allowed = ((JArray)policy["allowedModels"]).Values<string>().ToList();
        var chain = (JArray)fallback["chain"];
        var maxDepth = (int)fallback["maxDepth"];
        var current = requested;
        for (var depth = 0; depth < maxDepth; depth++)
        {
          var step = current;
          var edge = chain.FirstOrDefault(e => (string)e["from"] == step);
          if (edge == null) { break; }
          var next = (string)edge["to"];
          if (!allowed.Contains(next)) { break; }
          current = next;
        }
        return current;
      }

@{
        var policy = (JObject)context.Variables["effectivePolicy"];
        var effective = (string)context.Variables["effectiveModel"];
        if (string.Equals((string)policy["resolution"], "default", StringComparison.Ordinal)) { return effective; }
        var deployments = policy["modelDeployments"] as JArray;
        if (deployments == null) { return ""; }
        var mapping = deployments.FirstOrDefault(entry => (string)entry["modelKey"] == effective);
        return mapping == null || mapping["providerDeploymentName"] == null ? "" : (string)mapping["providerDeploymentName"];
      }

