@{
        var policy = (JObject)context.Variables["effectivePolicy"];
        var tiers = policy["throttleTiers"] as JArray;
        if (tiers == null || tiers.Count == 0) { return ""; }

        var names = new [] {
          "remainingThrottleOrganizationAllTokens",
          "remainingThrottleTeamAllTokens",
          "remainingThrottleSubjectAllTokens",
          "remainingThrottleApplicationAllTokens",
          "remainingThrottleOrganizationModelTokens",
          "remainingThrottleTeamModelTokens",
        };
        var selected = "";
        var selectedSeverity = 0;
        foreach (var tier in tiers)
        {
          if ((string)tier["accountingBasis"] != "apim-estimated-total-tokens") { continue; }
          var name = "";
          var scope = (string)tier["scope"];
          var modelScope = (string)tier["modelScope"];
          if (scope == "organization" && modelScope == "all-models") { name = names[0]; }
          else if (scope == "team" && modelScope == "all-models") { name = names[1]; }
          else if (scope == "subject" && modelScope == "all-models") { name = names[2]; }
          else if (scope == "application" && modelScope == "all-models") { name = names[3]; }
          else if (scope == "organization" && modelScope == "per-model" && (string)tier["modelKey"] == (string)context.Variables["effectiveModel"]) { name = names[4]; }
          else if (scope == "team" && modelScope == "per-model" && (string)tier["modelKey"] == (string)context.Variables["effectiveModel"]) { name = names[5]; }
          if (string.IsNullOrEmpty(name) || !context.Variables.ContainsKey(name)) { continue; }
          var quota = Convert.ToInt64(tier["againstTokenQuota"]);
          if (quota <= 0) { continue; }
          var used = Convert.ToInt64(context.Variables["throttleMeasurementQuota"]) - Convert.ToInt64(context.Variables[name]);
          var consumedBasisPoints = ((decimal)used / (decimal)quota) * 10000m;
          var at = Convert.ToInt64(tier["atBasisPoints"]);
          var tierCode = (string)tier["tierCode"];
          var severity = tierCode == "tier-minimal" ? 2 : tierCode == "tier-reduced" ? 1 : 0;
          if (severity == 0) { continue; }
          if (consumedBasisPoints >= at && severity > selectedSeverity) { selectedSeverity = severity; selected = tierCode; }
        }
        return selected;
      }

inbound.set-body:
@{
        var body = (JObject)context.Variables["requestBody"];
        body["model"] = (string)context.Variables["providerDeploymentName"];
        if (context.Operation.Id == "createChatCompletion" && body["stream"] != null && (bool)body["stream"])
        {
          var streamOptions = body["stream_options"] as JObject ?? new JObject();
          streamOptions["include_usage"] = true;
          body["stream_options"] = streamOptions;
        }
        return body.ToString(Newtonsoft.Json.Formatting.None);
      }

