when.condition:
@{
          var pooled = "{{pooled-model-deployments}}";
          if (string.IsNullOrWhiteSpace(pooled)) { return false; }
          var dispatched = (string)context.Variables["effectiveModel"];
          return pooled.Split(',').Any(entry => entry.Trim().Length > 0 && string.Equals(entry.Trim(), dispatched, StringComparison.Ordinal));
        }

when.set-body:
@{
            var unchanged = context.Response.Body.As<string>(preserveContent: true);
            var request = (JObject)context.Variables["requestBody"];

            var chatFormat = request["response_format"] as JObject;
            if (chatFormat != null && (string)chatFormat["type"] != "text") { return unchanged; }
            var responsesFormat = request["text"] as JObject;
            if (responsesFormat != null && responsesFormat["format"] != null && (string)responsesFormat["format"]["type"] != "text") { return unchanged; }

            JObject body;
            try { body = context.Response.Body.As<JObject>(preserveContent: true); }
            catch { return unchanged; }
            if (body == null) { return unchanged; }

            var notice = "{{substitution-notice-text}}".Replace("{model}", (string)context.Variables["effectiveModel"]) + "\n\n";

            if (context.Operation.Id == "createChatCompletion")
            {
              var choices = body["choices"] as JArray;
              if (choices == null || choices.Count != 1) { return unchanged; }
              var message = choices[0]["message"] as JObject;
              if (message == null || message["tool_calls"] != null || message["function_call"] != null) { return unchanged; }
              var content = message["content"];
              if (content == null || content.Type != JTokenType.String || string.IsNullOrEmpty((string)content)) { return unchanged; }
              message["content"] = notice + (string)content;
              return body.ToString(Newtonsoft.Json.Formatting.None);
            }

            var output = body["output"] as JArray;
            if (output == null) { return unchanged; }
            if (output.Any(item => (string)item["type"] != "message")) { return unchanged; }
            var first = output.FirstOrDefault(item => (string)item["type"] == "message") as JObject;
            if (first == null) { return unchanged; }
            var parts = first["content"] as JArray;
            if (parts == null || parts.Count == 0) { return unchanged; }
            var text = parts.FirstOrDefault(part => (string)part["type"] == "output_text") as JObject;
            if (text == null || text["text"] == null || text["text"].Type != JTokenType.String) { return unchanged; }
            text["text"] = notice + (string)text["text"];
            return body.ToString(Newtonsoft.Json.Formatting.None);
          }
